844→                        onClick={() =>
845→                          setCurrentPage((p) => Math.min(totalPages, p + 1))
846→                        }
847→                      >
848→                        Next
849→                      </Button>
850→                    </InlineStack>
851→                  </Box>
852→                </>
853→              )}
854→            </Card>
855→          </Layout.Section>
856→
857→        </Layout>
