 72→          Zip Code Checker — live widget loads on your storefront
 73→        </p>
 74→      </div>
 75→    </div>
 76→  </div>
 77→  <script>
 78→  (function() {
 79→    var bid = "{{ block.id }}";
 80→    function check() {
