604→                }
605→              }
606→
607→              var wBtn = document.getElementById(wid + "-wl-btn");
608→              if (wBtn) {
609→                wBtn.addEventListener("click", function () {
610→                  var nameEl = document.getElementById(wid + "-wl-name");
