616→                });
617→              }
618→            }
619→          }
620→
621→          // Block/unblock Add to Cart based on result (if merchant enabled this)
622→          if (cfg.blockCartOnInvalid) {
623→            var ATC_SELECTORS = [
624→              'button[name="add"]',
625→              '.product-form__submit',
626→              '[data-product-add]',
627→              '.btn--add-to-cart',
628→              '.product-form button[type="submit"]',
629→              'button.shopify-payment-button__button',
630→              '.shopify-payment-button button',
631→              'button.product-form__cart-submit'
632→            ].join(',');
633→
634→            try {
635→              var atcBtns = document.querySelectorAll(ATC_SELECTORS);
636→              atcBtns.forEach(function(b) {
637→                if (!b.closest('#zcc-widget, [data-zcc-widget]')) { // Don't touch our own widget's button
638→                  if (data.allowed) {
639→                    b.disabled = false;
640→                    b.style.opacity = '';
641→                    b.title = b.getAttribute('data-zcc-orig-title') || '';
642→                    b.removeAttribute('data-zcc-orig-title');
643→                    b.removeAttribute('data-zcc-blocked');
644→                  } else {
645→                    b.setAttribute('data-zcc-orig-title', b.title || '');
646→                    b.disabled = true;
647→                    b.style.opacity = '0.5';
648→                    b.title = 'Please enter a valid ZIP code to continue';
649→                    b.setAttribute('data-zcc-blocked', 'true');
650→                  }
651→                }
652→              });
653→            } catch(e) { /* DOM query may fail in some contexts */ }
654→          }
655→        })
656→        .catch(function () {
657→          setBtnLoading(false);
658→          res.innerHTML = '<div class="zcc-result fail"><div class="zcc-result-icon">' + ICONS.xCircle + '</div><div class="zcc-result-content"><div class="zcc-result-message">Something went wrong. Please try again.</div></div></div>';
659→          try {
660→            sessionStorage.removeItem('zcc:valid');
661→            sessionStorage.removeItem('zcc:zip');
662→            window.dispatchEvent(new CustomEvent('zcc:validated', { detail: { valid: false, zip: zip } }));
663→          } catch(e) {}
664→        });
665→    }
666→
667→    btn.addEventListener("click", checkZip);
668→    inp.addEventListener("keydown", function (e) {
669→      if (e.key === "Enter") checkZip();
