691→  function joinWaitlist(zip, email, name, wBtn) {
692→    wBtn.disabled = true;
693→    var wBtnIcon = wBtn.querySelector('.zcc-wl-btn-icon');
694→    var wBtnLabel = wBtn.querySelector('.zcc-wl-btn-label');
695→    if (wBtnIcon) wBtnIcon.innerHTML = ICONS.spinner;
696→    if (wBtnLabel) wBtnLabel.textContent = 'Submitting\u2026';
697→    if (!wBtnIcon && !wBtnLabel) wBtn.textContent = 'Submitting\u2026';
698→
699→    var payload = { shop: SHOP, zip: zip, email: email };
700→    if (name) payload.name = name;
701→
702→    fetch(API_BASE + "/api/waitlist", {
703→      method: "POST",
704→      headers: { "Content-Type": "application/json" },
705→      body: JSON.stringify(payload),
706→    })
707→      .then(function (r) { return r.json(); })
708→      .then(function (data) {
709→        var wlEl = wBtn.closest(".zcc-wl");
710→        if (data.success) {
711→          if (wlEl) wlEl.innerHTML =
712→            '<div class="zcc-wl-success">' +
713→            '<span class="zcc-wl-success-icon">' + ICONS.checkmark + '</span>' +
714→            '<span>Your request has been submitted! We\u2019ll notify you when delivery is available.</span>' +
715→            '</div>';
716→        } else {
717→          wBtn.disabled = false;
718→          if (wBtnIcon) wBtnIcon.innerHTML = ICONS.mail;
719→          if (wBtnLabel) wBtnLabel.textContent = 'Submit Request';
720→          if (!wBtnIcon && !wBtnLabel) wBtn.textContent = 'Submit Request';
721→        }
722→      })
723→      .catch(function () {
724→        wBtn.disabled = false;
725→        if (wBtnIcon) wBtnIcon.innerHTML = ICONS.mail;
726→        if (wBtnLabel) wBtnLabel.textContent = 'Submit Request';
727→        if (!wBtnIcon && !wBtnLabel) wBtn.textContent = 'Submit Request';
728→      });
729→  }
